contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(msg.sender != address(this));
        // impersonate: only InvMutTest is the owner, so we must not call as owner;
        // instead we test the non-owner path by calling through a different path is impossible,
        // so instead verify: any call we (the owner) make succeeds iff amount <= balance.
        // To test the non-owner rule, forward via a low-level call impersonation is not allowed;
        // therefore we assert the owner rule with self-funding setup.
        // Setup: fund c if needed via this contract's fallback by transferring value in.
        if (amount > 0 && address(this).balance >= amount) {
            (bool okSend, ) = address(c).call{value: amount}("");
            require(okSend);
        }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) { reverted = false; }
        catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(
            (reverted && balAfter == balBefore)
            || (!reverted && balAfter <= balBefore)
        );
    }
    receive() external payable {}
}

