contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amt) public payable {
        require(amt < type(uint256).max);
        require(address(this).balance >= amt);
        // Fund C by having it send amt to this test (owner -> allowed, C holds amt from msg.value).
        c.sendTo(address(this), amt);
        uint balBefore = address(c).balance;
        // A call exceeding C's balance must revert.
        bool overReverted;
        try c.sendTo(address(0xdead), amt + 1) { overReverted = false; }
        catch { overReverted = true; }
        // C's balance must be untouched by the reverted call.
        assert(overReverted && address(c).balance == balBefore);
        // The failed call must not lock funds: C can still send its full balance out.
        bool afterReverted;
        try c.sendTo(address(this), balBefore) { afterReverted = false; }
        catch { afterReverted = true; }
        assert(!afterReverted && address(c).balance == 0);
    }
    receive() external payable {}
}

